static function ApplyStandardCam(harry H)
{
    if (!SafeToTouchCam(H))
        return;

    EnsureCam(H);
    if (H.Cam == None)
        return;

    H.Cam.PlayerHarry = H;
    H.Level.PlayerHarryActor = H;

    if (H.Cam.CamTarget != None)
    {
        H.Cam.CamTarget.Cam = H.Cam;
        H.Cam.CamTarget.SetAttachedTo(H);
    }

    if (H.Cam.CameraMode == H.Cam.ECamMode.CM_Standard)
    {
        H.Cam.InitTarget(H);
        if (HPVersusHarry(H) != None)
            HPVersusHarry(H).ForceVersusViewTarget();
        return;
    }

    H.Cam.SetCameraMode(H.Cam.ECamMode.CM_Standard);
    H.Cam.GotoState('StateStandardCam');
    H.Cam.InitTarget(H);
    H.Cam.InitPositionAndRotation(True);
    if (HPVersusHarry(H) != None)
        HPVersusHarry(H).ForceVersusViewTarget();
}

